interface ChannelEvents { "order-placed": { orderId: string; totalCents: number } }

class Channel extends EventTarget {
  publish<K extends keyof ChannelEvents>(type: K, payload: ChannelEvents[K]): void {
    this.dispatchEvent(new CustomEvent(type as string, { detail: payload }));
  }
  subscribe<K extends keyof ChannelEvents>(type: K, fn: (p: ChannelEvents[K]) => void): () => void {
    const h = (e: Event) => fn((e as CustomEvent<ChannelEvents[K]>).detail);
    this.addEventListener(type as string, h);
    return () => this.removeEventListener(type as string, h);   // unsubscribe token
  }
}
